parameters.query:
CREATE TABLE IF NOT EXISTS public.schema_migrations (
  id SERIAL PRIMARY KEY,
  version VARCHAR(50) UNIQUE NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied_at TIMESTAMPTZ DEFAULT NOW()
);

parameters.jsCode:
const executedItems = $input.all() || [];
const executedVersions = new Set(
  executedItems
    .map(item => item.json?.version)
    .filter(Boolean)
);

// Cada migration executa o DDL e já grava seu registro com RETURNING atômico
const allMigrations = [
  {
    version: '20261026_001',
    name: 'Tabela configs e constraints',
    sql: `
      CREATE TABLE IF NOT EXISTS public.configs (
        id SERIAL PRIMARY KEY,
        created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT NOW(),
        key VARCHAR(255) UNIQUE,
        value VARCHAR(255)
      );
      CREATE UNIQUE INDEX IF NOT EXISTS configs_key_unique_idx ON public.configs (key);

      INSERT INTO public.schema_migrations (version, name, applied_at)
      VALUES ('20261026_001', 'Tabela configs e constraints', NOW())
      ON CONFLICT (version) DO NOTHING
      RETURNING version, name, applied_at;
    `
  },
  {
    version: '20261026_002',
    name: 'Ajuste whatsapp_loja opcional e indices',
    sql: `
      ALTER TABLE public.lojas ALTER COLUMN whatsapp_loja DROP NOT NULL;
      CREATE INDEX IF NOT EXISTS idx_lojas_whatsapp ON public.lojas (whatsapp_loja);
      CREATE INDEX IF NOT EXISTS idx_lojas_ativo ON public.lojas (ativo);

      INSERT INTO public.schema_migrations (version, name, applied_at)
      VALUES ('20261026_002', 'Ajuste whatsapp_loja opcional e indices', NOW())
      ON CONFLICT (version) DO NOTHING
      RETURNING version, name, applied_at;
    `
  },
  {
    version: '20261026_003',
    name: 'Indices de performance em mensagens e pessoas',
    sql: `
      CREATE INDEX IF NOT EXISTS idx_mensagens_loja_id ON public.mensagens (loja_id);
      CREATE INDEX IF NOT EXISTS idx_mensagens_message_id ON public.mensagens (message_id);
      CREATE INDEX IF NOT EXISTS idx_mensagens_timestamp ON public.mensagens (timestamp_mensagem DESC);
      CREATE INDEX IF NOT EXISTS idx_pessoas_loja_whatsapp ON public.pessoas (loja_id, whatsapp);

      INSERT INTO public.schema_migrations (version, name, applied_at)
      VALUES ('20261026_003', 'Indices de performance em mensagens e pessoas', NOW())
      ON CONFLICT (version) DO NOTHING
      RETURNING version, name, applied_at;
    `
  },
  {
    version: '20261026_004',
    name: 'Tabela criativos e campos de SLA e anuncios',
    sql: `
      CREATE TABLE IF NOT EXISTS public.criativos (
        id SERIAL PRIMARY KEY,
        loja_id INTEGER NOT NULL REFERENCES public.lojas(id) ON DELETE CASCADE,
        ad_id VARCHAR(100) NOT NULL,
        titulo VARCHAR(255),
        tema TEXT,
        canal VARCHAR(50) DEFAULT 'instagram',
        media_url TEXT,
        total_mensagens INTEGER DEFAULT 0,
        total_pessoas_unicas INTEGER DEFAULT 0,
        primeira_mensagem_at TIMESTAMPTZ DEFAULT NOW(),
        ultima_mensagem_at TIMESTAMPTZ DEFAULT NOW(),
        created_at TIMESTAMPTZ DEFAULT NOW(),
        updated_at TIMESTAMPTZ DEFAULT NOW(),
        CONSTRAINT uq_criativos_loja_ad UNIQUE (loja_id, ad_id)
      );

      CREATE INDEX IF NOT EXISTS idx_criativos_loja_id ON public.criativos(loja_id);
      CREATE INDEX IF NOT EXISTS idx_criativos_ad_id ON public.criativos(ad_id);
      CREATE INDEX IF NOT EXISTS idx_criativos_canal ON public.criativos(canal);

      ALTER TABLE public.mensagens ADD COLUMN IF NOT EXISTS is_ad BOOLEAN DEFAULT false;
      ALTER TABLE public.mensagens ADD COLUMN IF NOT EXISTS criativo_id INTEGER REFERENCES public.criativos(id) ON DELETE SET NULL;
      ALTER TABLE public.mensagens ADD COLUMN IF NOT EXISTS ctwa_clid VARCHAR(255);
      ALTER TABLE public.mensagens ADD COLUMN IF NOT EXISTS tempo_resposta_segundos INTEGER DEFAULT NULL;
      ALTER TABLE public.mensagens ADD COLUMN IF NOT EXISTS respondida_em TIMESTAMPTZ DEFAULT NULL;
      ALTER TABLE public.mensagens ADD COLUMN IF NOT EXISTS respondida_por_mensagem_id VARCHAR(255) DEFAULT NULL;

      CREATE INDEX IF NOT EXISTS idx_mensagens_criativo_id ON public.mensagens(criativo_id);
      CREATE INDEX IF NOT EXISTS idx_mensagens_is_ad ON public.mensagens(is_ad);
      CREATE INDEX IF NOT EXISTS idx_mensagens_tempo_resposta ON public.mensagens(tempo_resposta_segundos) WHERE tempo_resposta_segundos IS NOT NULL;
      CREATE INDEX IF NOT EXISTS idx_mensagens_respondida_em ON public.mensagens(respondida_em);
      CREATE INDEX IF NOT EXISTS idx_mensagens_inbound_pendente ON public.mensagens(loja_id, pessoa_id, direcao, respondida_em) WHERE direcao = 'inbound' AND respondida_em IS NULL;

      ALTER TABLE public.pessoas ADD COLUMN IF NOT EXISTS ultimo_criativo_id INTEGER REFERENCES public.criativos(id) ON DELETE SET NULL;
      CREATE INDEX IF NOT EXISTS idx_pessoas_ultimo_criativo ON public.pessoas(ultimo_criativo_id);

      INSERT INTO public.schema_migrations (version, name, applied_at)
      VALUES ('20261026_004', 'Tabela criativos e campos de SLA e anuncios', NOW())
      ON CONFLICT (version) DO NOTHING
      RETURNING version, name, applied_at;
    `
  },
  {
    version: '20261026_005',
    name: 'Token publico de conexao do lojista em lojas',
    sql: `
      ALTER TABLE public.lojas ADD COLUMN IF NOT EXISTS connect_token UUID DEFAULT gen_random_uuid();
      UPDATE public.lojas SET connect_token = gen_random_uuid() WHERE connect_token IS NULL;
      ALTER TABLE public.lojas ALTER COLUMN connect_token SET NOT NULL;
      CREATE UNIQUE INDEX IF NOT EXISTS idx_lojas_connect_token ON public.lojas(connect_token);

      INSERT INTO public.schema_migrations (version, name, applied_at)
      VALUES ('20261026_005', 'Token publico de conexao do lojista em lojas', NOW())
      ON CONFLICT (version) DO NOTHING
      RETURNING version, name, applied_at;
    `
  }
];

const pending = allMigrations.filter(m => !executedVersions.has(m.version));

if (pending.length === 0) {
  return [
    {
      json: {
        hasPending: false,
        message: 'Todas as migrações já foram aplicadas. Nenhuma ação necessária.',
        totalApplied: executedVersions.size,
        pendingCount: 0
      }
    }
  ];
}

return pending.map(m => ({
  json: {
    hasPending: true,
    version: m.version,
    name: m.name,
    sql: m.sql.trim()
  }
}));

return {
  json: {
    status: 'UP_TO_DATE',
    message: 'Banco de dados 100% atualizado. Nenhuma migration pendente.'
  }
};

const items = $input.all() || [];
const applied = items.map(item => item.json?.version || item.json?.name).filter(Boolean);
return [
  {
    json: {
      status: 'SUCCESS',
      message: `Migrações executadas com sucesso: ${applied.length} aplicada(s).`,
      appliedVersions: applied
    }
  }
];
